import React, { useState } from "react";
import "../Dashboard/WeatherDashboard.css"
import { useEffect } from "react";
// import "./WeatherResults.css"; // Import the CSS file
import "../styles/global.css";

function WeatherForecast({results, hourlyResults}) {
    let weekDay;

    const divs = [];
    for(let i=0; i<14; i++){
        const datetime = hourlyResults.days[i];
        weekDay = convertDateTimeToWeekday(datetime);
        divs.push(
            <div class="column border-bottom-white flex" key={i}>
                    <p>{weekDay}</p>
                    <p></p>
            </div>
        );
    }

    const convertDateTimeToWeekday = (datetime) => {
        const date = new Date(datetime + 'T00:00:00');
        const weekDays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];   
        let dayIndex = date.getDay();
        return weekDay = weekDays[dayIndex];
    }

    return (
        <>
            <div class="row w-25" className="card">
                {divs}
            </div>
        </>
    );

}

export default WeatherForecast;
